"""Move particles under their mutual gravity on the GPU and summarize the result.

Usage: uv run main.py <input-file>

The input file holds "<count> <steps> <dt>" and then one "<x> <y> <vx> <vy>"
line per particle. Each step runs two compute kernels on the GPU: one computes
every acceleration from the positions the step started with, the other
advances velocities and then positions.
"""

import struct
import sys

import numpy as np
import wgpu

WORKGROUP_SIZE = 64

SHADER = """
struct Params {
    count: u32,
    dt: f32,
    pad0: u32,
    pad1: u32,
}

@group(0) @binding(0) var<uniform> params: Params;
@group(0) @binding(1) var<storage, read_write> pos: array<vec2<f32>>;
@group(0) @binding(2) var<storage, read_write> vel: array<vec2<f32>>;
@group(0) @binding(3) var<storage, read_write> acc: array<vec2<f32>>;

@compute @workgroup_size(%(wg)d)
fn accelerate(@builtin(global_invocation_id) gid: vec3<u32>) {
    let i = gid.x;
    if (i >= params.count) {
        return;
    }
    let pi = pos[i];
    var a = vec2<f32>(0.0, 0.0);
    for (var j: u32 = 0u; j < params.count; j = j + 1u) {
        // The j == i term is zero, so no branch is needed.
        let d = pos[j] - pi;
        let r2 = dot(d, d) + 0.01;
        a = a + d / (r2 * sqrt(r2));
    }
    acc[i] = a;
}

@compute @workgroup_size(%(wg)d)
fn advance(@builtin(global_invocation_id) gid: vec3<u32>) {
    let i = gid.x;
    if (i >= params.count) {
        return;
    }
    let v = vel[i] + acc[i] * params.dt;
    vel[i] = v;
    pos[i] = pos[i] + v * params.dt;
}
""" % {"wg": WORKGROUP_SIZE}


def read_input(path):
    with open(path) as f:
        tokens = f.read().split()
    count = int(tokens[0])
    steps = int(tokens[1])
    dt = float(tokens[2])
    values = np.array(tokens[3 : 3 + 4 * count], dtype=np.float64).reshape(count, 4)
    pos = values[:, 0:2].astype(np.float32)
    vel = values[:, 2:4].astype(np.float32)
    return count, steps, dt, pos, vel


def simulate(count, steps, dt, pos, vel):
    adapter = wgpu.gpu.request_adapter_sync(power_preference="high-performance")
    device = adapter.request_device_sync()

    usage = wgpu.BufferUsage.STORAGE | wgpu.BufferUsage.COPY_SRC
    pos_buf = device.create_buffer_with_data(data=pos.tobytes(), usage=usage)
    vel_buf = device.create_buffer_with_data(data=vel.tobytes(), usage=usage)
    acc_buf = device.create_buffer(size=count * 8, usage=usage)
    params_buf = device.create_buffer_with_data(
        data=struct.pack("<IfII", count, dt, 0, 0),
        usage=wgpu.BufferUsage.UNIFORM,
    )

    bind_group_layout = device.create_bind_group_layout(
        entries=[
            {
                "binding": 0,
                "visibility": wgpu.ShaderStage.COMPUTE,
                "buffer": {"type": "uniform"},
            },
            {
                "binding": 1,
                "visibility": wgpu.ShaderStage.COMPUTE,
                "buffer": {"type": "storage"},
            },
            {
                "binding": 2,
                "visibility": wgpu.ShaderStage.COMPUTE,
                "buffer": {"type": "storage"},
            },
            {
                "binding": 3,
                "visibility": wgpu.ShaderStage.COMPUTE,
                "buffer": {"type": "storage"},
            },
        ]
    )
    pipeline_layout = device.create_pipeline_layout(
        bind_group_layouts=[bind_group_layout]
    )
    module = device.create_shader_module(code=SHADER)
    accelerate = device.create_compute_pipeline(
        layout=pipeline_layout,
        compute={"module": module, "entry_point": "accelerate"},
    )
    advance = device.create_compute_pipeline(
        layout=pipeline_layout,
        compute={"module": module, "entry_point": "advance"},
    )

    bind_group = device.create_bind_group(
        layout=bind_group_layout,
        entries=[
            {"binding": 0, "resource": {"buffer": params_buf, "offset": 0, "size": params_buf.size}},
            {"binding": 1, "resource": {"buffer": pos_buf, "offset": 0, "size": pos_buf.size}},
            {"binding": 2, "resource": {"buffer": vel_buf, "offset": 0, "size": vel_buf.size}},
            {"binding": 3, "resource": {"buffer": acc_buf, "offset": 0, "size": acc_buf.size}},
        ],
    )

    groups = (count + WORKGROUP_SIZE - 1) // WORKGROUP_SIZE
    encoder = device.create_command_encoder()
    for _ in range(steps):
        # Each compute pass finishes before the next begins, so every
        # acceleration reads the positions from before this step's advance.
        for pipeline in (accelerate, advance):
            compute_pass = encoder.begin_compute_pass()
            compute_pass.set_pipeline(pipeline)
            compute_pass.set_bind_group(0, bind_group)
            compute_pass.dispatch_workgroups(groups)
            compute_pass.end()
    device.queue.submit([encoder.finish()])

    final_pos = np.frombuffer(device.queue.read_buffer(pos_buf), dtype=np.float32)
    final_vel = np.frombuffer(device.queue.read_buffer(vel_buf), dtype=np.float32)
    return final_pos.reshape(count, 2).astype(np.float64), final_vel.reshape(count, 2).astype(np.float64)


def summarize(pos, vel):
    cx, cy = pos.mean(axis=0)
    px, py = vel.sum(axis=0)
    kinetic = ((vel * vel).sum(axis=1) / 2).sum()
    d2 = ((pos[:, 0] - cx) ** 2 + (pos[:, 1] - cy) ** 2).mean()
    spread = np.sqrt(d2)
    return [
        f"CENTER {cx:.6f} {cy:.6f}",
        f"MOMENTUM {px:.6f} {py:.6f}",
        f"KINETIC {kinetic:.6f}",
        f"SPREAD {spread:.6f}",
    ]


def main(argv):
    if len(argv) != 2:
        print("usage: main.py <input-file>", file=sys.stderr)
        return 2
    count, steps, dt, pos, vel = read_input(argv[1])
    pos, vel = simulate(count, steps, dt, pos, vel)
    for line in summarize(pos, vel):
        print(line)
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))

